{"command":"cat << 'EOF' > main.py
import sys, os, re, glob
from pathlib import Path
import json

def parse_python_imports(file_path):
    imports = []
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            for line in f:
                if line.startswith('import '):
                    for mod in line[7:].split(','):
                        imports.append(mod.strip().split()[0])
                elif line.startswith('from '):
                    parts = line.split(' import ')
                    if len(parts) == 2:
                        imports.append(parts[0][5:].strip())
    except Exception:
        pass
    return imports

def build_graph(entrypoints):
    graph = {}
    queue = list(entrypoints)
    visited = set()
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        graph[curr] = []
        if curr.endswith('.py'):
            deps = parse_python_imports(curr)
            for d in deps:
                target = d + ".py"
                if os.path.exists(target):
                    graph[curr].append(target)
                    queue.append(target)
    return graph

def cmd_explain(file1, file2):
    graph = build_graph([file1])
    visited = set()
    queue = [[file1]]
    while queue:
        path = queue.pop(0)
        curr = path[-1]
        if curr == file2:
            print(" -> ".join(path))
            return
        if curr in visited: continue
        visited.add(curr)
        for nxt in graph.get(curr, []):
            queue.append(path + [nxt])

def main():
    if len(sys.argv) < 2:
        print("Error: requires at least 1 arg(s), only received 0", file=sys.stderr)
        sys.exit(1)

    cmd = sys.argv[1]
    if cmd == "version" or cmd == "--version" or cmd == "-v":
        print("dep-tree version v0.23.4")
        sys.exit(0)
    elif cmd == "explain":
        cmd_explain(sys.argv[2], sys.argv[3])
    else:
        print("Error: exit status 1", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
