        key_val = line.strip().split(':', 1)
        if len(key_val) == 2:
            key = key_val[0].strip().strip("'").strip('"')
            val = key_val[1].strip()

            # Adjust path based on indent
            # Each level of indent in standard yaml is 2 spaces
            level = indent // 2
            path = path[:level]
            path.append(key)

            curr = result
            for p in path[:-1]:
                if p not in curr: curr[p] = {}
                curr = curr[p]
            if val:
                curr[key] = val
            else:
                curr[key] = {}
        elif line.strip().startswith('- '):
            val = line.strip()[2:].strip().strip("'").strip('"')
            level = indent // 2
            path = path[:level]

            curr = result
            for p in path:
                if p not in curr: curr[p] = []
                curr = curr[p]
            if isinstance(curr, list):
                curr.append(val)
            else:
                # If it's a dict but we found a list item
                pass
    return result

