#!/usr/bin/env python3
import sys, os, re, json, glob
from pathlib import Path
import ast

def find_file(base_dir, import_path, exts):
    for ext in exts:
        p = os.path.join(base_dir, import_path + ext)
        if os.path.exists(p): return p
        p = os.path.join(base_dir, import_path, '__init__' + ext)
        if os.path.exists(p): return p
        p = os.path.join(base_dir, import_path, 'index' + ext)
        if os.path.exists(p): return p
    return None

def parse_py(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read(), filename=file_path)
    except Exception:
        return []
    deps = []
    base_dir = os.path.dirname(file_path)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for n in node.names:
                deps.append(n.name.replace('.', '/'))
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                deps.append(node.module.replace('.', '/'))

    resolved = []
    for d in deps:
        p = find_file(base_dir, d, ['.py'])
        if p: resolved.append(os.path.normpath(p))
    return resolved

def parse_js(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        return []
    text = re.sub(r'//.*', '', text)
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.DOTALL)
    deps = []
    for m in re.finditer(r'(?:import|export)\s+.*?from\s+[\'"]([^\'"]+)[\'"]', text):
        deps.append(m.group(1))
    for m in re.finditer(r'import\s+[\'"]([^\'"]+)[\'"]', text):
        deps.append(m.group(1))

    resolved = []
    base_dir = os.path.dirname(file_path)
    for d in deps:
        if d.startswith('./') or d.startswith('../'):
            p = find_file(base_dir, d, ['.js', '.ts', '.jsx', '.tsx', '.mjs', '.cjs'])
            if p: resolved.append(os.path.normpath(p))
    return resolved

def parse_go(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        return []
    text = re.sub(r'//.*', '', text)
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.DOTALL)
    deps = []
    for m in re.finditer(r'import\s+"([^"]+)"', text):
        deps.append(m.group(1))
    for block in re.finditer(r'import\s+\((.*?)\)', text, flags=re.DOTALL):
        for line in block.group(1).split('\n'):
            line = line.strip()
            if line.startswith('"') and line.endswith('"'):
                deps.append(line.strip('"'))
            elif ' "' in line and line.endswith('"'):
                deps.append(line.split(' "')[1].strip('"'))

    resolved = []
    base_dir = os.path.dirname(file_path)
    for d in deps:
        p = os.path.join(d, os.path.basename(d) + '.go')
        if os.path.exists(d):
            for f in glob.glob(os.path.join(d, '*.go')):
                resolved.append(os.path.normpath(f))
        else:
            resolved.append(d)
    return resolved

def parse_file(file_path):
    if file_path.endswith('.py'): return parse_py(file_path)
    if file_path.endswith(('.js','.ts','.jsx','.tsx')): return parse_js(file_path)
    if file_path.endswith('.go'): return parse_go(file_path)
    return []

def build_graph(entrypoints):
    graph = {}
    queue = list(entrypoints)
    visited = set()
    while queue:
        curr = queue.pop(0)
        if curr in visited: continue
        visited.add(curr)
        deps = parse_file(curr)
        graph[curr] = deps
        queue.extend([d for d in deps if d not in visited])
    return graph

def cmd_explain(file1, file2):
    graph = build_graph([file1])
    visited = set()
    queue = [[file1]]
    while queue:
        path = queue.pop(0)
        curr = path[-1]
        if curr == file2:
            print(" -> ".join(path))
            return
        if curr in visited: continue
        visited.add(curr)
        for nxt in graph.get(curr, []):
            queue.append(path + [nxt])

def cmd_entropy(entrypoints):
    graph = build_graph(entrypoints)
    nodes = []
    links = []
    id_map = {}
    for i, file in enumerate(graph.keys()):
        id_map[file] = i
        nodes.append({"id": i, "fileName": file, "isEntrypoint": file in entrypoints})
    for file, deps in graph.items():
        for dep in deps:
            if dep in id_map:
                links.append({"source": id_map[file], "target": id_map[dep]})
    html = f"<html><body><script>var data = {json.dumps({'nodes': nodes, 'links': links})}</script></body></html>"
    with open('/tmp/index.html', 'w') as f:
        f.write(html)
    os.system("xdg-open /tmp/index.html 2>/dev/null")

def cmd_tree(entrypoints):
    graph = build_graph(entrypoints)
    def print_tree(node, prefix="", is_last=True, is_root=False):
        if not is_root:
            print(prefix + ("└─▷" if is_last else "├─▷") + node)
        else:
            print(node)
            print("│")
        deps = graph.get(node, [])
        for i, dep in enumerate(deps):
            is_last_child = (i == len(deps) - 1)
            child_prefix = prefix + ("  " if is_last else "│ ") if not is_root else ""
            print_tree(dep, child_prefix, is_last_child, False)

    for entry in entrypoints:
        print_tree(entry, is_root=True)

def parse_yaml(text):
    config = {'check': {'entrypoints': [], 'deny': {}, 'allow': {}, 'aliases': {}}}
    lines = text.split('\n')
    mode = None
