    for line in lines:
        sline = line.strip()
        if not sline or sline.startswith('#'): continue
        if sline == 'entrypoints:': mode = 'entrypoints'
        elif sline == 'deny:': mode = 'deny'
        elif sline == 'allow:': mode = 'allow'
        elif sline == 'aliases:': mode = 'aliases'
        elif mode == 'entrypoints' and sline.startswith('-'):
            config['check']['entrypoints'].append(sline[1:].strip().strip("'\""))
        elif mode == 'deny' or mode == 'allow' or mode == 'aliases':
            if sline.endswith(':'):
                curr_key = sline[:-1].strip().strip("'\"")
                config['check'][mode][curr_key] = []
            elif sline.startswith('-') and curr_key:
                val = sline[1:].strip()
                if val.startswith('to:'): val = val[3:].strip()
                val = val.strip("'\"")
                config['check'][mode][curr_key].append(val)
    return config

def cmd_check():
    if not os.path.exists('.dep-tree.yml'):
        print("Error: no config file found", file=sys.stderr)
