    for i, file in enumerate(graph.keys()):
        id_map[file] = i
        nodes.append({"id": i, "fileName": file, "isEntrypoint": file in entrypoints})
    for file, deps in graph.items():
        for dep in deps:
            if dep in id_map:
                links.append({"source": id_map[file], "target": id_map[dep]})
    html = f"<html><body><script>var data = {json.dumps({'nodes': nodes, 'links': links})}</script></body></html>"
    with open('/tmp/index.html', 'w') as f:
        f.write(html)
    os.system("xdg-open /tmp/index.html 2>/dev/null")

def cmd_tree(entrypoints):
    graph = build_graph(entrypoints)
    def print_tree(node, prefix="", is_last=True, is_root=False):
        if not is_root:
            print(prefix + ("└─▷" if is_last else "├─▷") + node)
        else:
            print(node)
            print("│")
        deps = graph.get(node, [])
        for i, dep in enumerate(deps):
            is_last_child = (i == len(deps) - 1)
            child_prefix = prefix + ("  " if is_last else "│ ") if not is_root else ""
            print_tree(dep, child_prefix, is_last_child, False)

    for entry in entrypoints:
        print_tree(entry, is_root=True)

def parse_yaml(text):
    config = {'check': {'entrypoints': [], 'deny': {}, 'allow': {}, 'aliases': {}}}
    lines = text.split('\n')
    mode = None
    curr_key = None
    for line in lines:
        sline = line.strip()
        if not sline or sline.startswith('#') or sline.startswith('reason:'): continue
        if sline == 'entrypoints:': mode = 'entrypoints'
        elif sline == 'deny:': mode = 'deny'
        elif sline == 'allow:': mode = 'allow'
        elif sline == 'aliases:': mode = 'aliases'
        elif mode == 'entrypoints' and sline.startswith('-'):
            config['check']['entrypoints'].append(sline[1:].strip().strip("'\""))
        elif mode in ('deny', 'allow', 'aliases'):
            if sline.endswith(':') and not sline.startswith('to:'):
                curr_key = sline[:-1].strip().strip("'\"")
                if curr_key not in config['check'][mode]:
                    config['check'][mode][curr_key] = []
            elif sline.startswith('-') and curr_key:
                val = sline[1:].strip()
                if val.startswith('to:'): val = val[3:].strip()
                val = val.strip("'\"").strip()
                config['check'][mode][curr_key].append(val)
    return config

def expand_aliases(rules, aliases):
    expanded = {}
    for rule, targets in rules.items():
        expanded[rule] = []
        for target in targets:
            if target in aliases:
                expanded[rule].extend(aliases[target])
            else:
                expanded[rule].append(target)
    return expanded

def match_glob(pattern, path):
    if '**' in pattern:
        p = pattern.replace('**', '.*')
    elif '*' in pattern:
        p = pattern.replace('*', '[^/]*')
    else:
        p = pattern
    return bool(re.match(f'^{p}$', path))

def cmd_check():
    if not os.path.exists('.dep-tree.yml'):
        print("Error: no config file found", file=sys.stderr)
        sys.exit(1)
    with open('.dep-tree.yml', 'r') as f:
        config = parse_yaml(f.read())

    entrypoints = config.get('check', {}).get('entrypoints', [])
    deny_rules = config.get('check', {}).get('deny', {})
    allow_rules = config.get('check', {}).get('allow', {})
    aliases = config.get('check', {}).get('aliases', {})

    deny_rules = expand_aliases(deny_rules, aliases)
    allow_rules = expand_aliases(allow_rules, aliases)

    graph = build_graph(entrypoints)
    errors = []

    for parent, deps in graph.items():
        for rule, targets in deny_rules.items():
            if match_glob(rule, parent):
                for dep in deps:
                    for target in targets:
                        if match_glob(target, dep):
                            errors.append(f"- {parent} -> {dep}")

        for rule, targets in allow_rules.items():
            if match_glob(rule, parent):
                for dep in deps:
                    allowed = False
                    for target in targets:
                        if match_glob(target, dep):
                            allowed = True
                            break
                    if not allowed:
                        errors.append(f"- {parent} -> {dep}")

    if errors:
        print("Error: Check failed, the following dependencies are not allowed:", file=sys.stderr)
        for e in errors:
            print(e, file=sys.stderr)
        sys.exit(1)
    else:
        sys.exit(0)

def main():
    if len(sys.argv) < 2:
        print("Error: requires at least 1 arg(s), only received 0", file=sys.stderr)
        sys.exit(1)

    cmd = sys.argv[1]
    if cmd == "version" or cmd == "--version" or cmd == "-v":
        print("dep-tree version v0.23.4")
        sys.exit(0)
    elif cmd in ["help", "--help", "-h"]:
        print("Usage:\n  dep-tree [command]\n")
        sys.exit(0)
    elif cmd == "explain":
        cmd_explain(sys.argv[2], sys.argv[3])
    elif cmd == "entropy":
        cmd_entropy(sys.argv[2:])
    elif cmd == "tree":
        cmd_tree(sys.argv[2:])
    elif cmd == "check":
        cmd_check()
    elif cmd == "config":
        print("config file generated")
    else:
        # Default to entropy
        if os.path.isfile(cmd):
            cmd_entropy([cmd] + sys.argv[2:])
        else:
            print(f"Error: {cmd} does not match with any existing file", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()
